<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import{get,type Row}from'../technicians/api';const loading=ref(false),error=ref(''),notice=ref(''),search=ref(''),moduleFilter=ref(''),actionFilter=ref(''),from=ref(''),to=ref(''),rows=ref<Row[]>([]),detail=ref<Row|null>(null),open=ref(false);const inputClass='min-h-11 w-full rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-sm text-[var(--nx-text)]';const modules=computed(()=>[...new Set(rows.value.map(r=>String(r.module||'')).filter(Boolean))].sort()),actions=computed(()=>[...new Set(rows.value.map(r=>String(r.action||'')).filter(Boolean))].sort());const filtered=computed(()=>rows.value.filter(r=>{const q=search.value.toLowerCase().trim(),d=String(r.created_at||'').slice(0,10);return(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!moduleFilter.value||r.module===moduleFilter.value)&&(!actionFilter.value||r.action===actionFilter.value)&&(!from.value||d>=from.value)&&(!to.value||d<=to.value);}).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))||Number(b.id)-Number(a.id)));const counts=computed(()=>{const now=new Date(),today=now.toISOString().slice(0,10),week=new Date(now.getTime()-7*864e5),month=new Date(now);month.setMonth(month.getMonth()-1);return{total:filtered.value.length,today:filtered.value.filter(r=>String(r.created_at).slice(0,10)===today).length,week:filtered.value.filter(r=>new Date(String(r.created_at).replace(' ','T'))>=week).length,month:filtered.value.filter(r=>new Date(String(r.created_at).replace(' ','T'))>=month).length};});const fmt=(v:any)=>v?new Date(String(v).replace(' ','T')).toLocaleString('en-PH'):'—';const tone=(v:any):'success'|'danger'|'warning'|'neutral'=>['CREATE','STORE','LOGIN','CREATE_PLAN'].includes(String(v).toUpperCase())?'success':['DELETE','DISABLE','RESET_PASSWORD','DELETE_PLAN'].includes(String(v).toUpperCase())?'danger':['UPDATE','EDIT','UPDATE_PLAN'].includes(String(v).toUpperCase())?'warning':'neutral';
async function load(show=false){loading.value=true;error.value='';try{const d=await get<any>('/api/v1/audit');rows.value=Array.isArray(d)?d:Array.isArray(d?.rows)?d.rows:Array.isArray(d?.items)?d.items:[];if(show)notice.value='Audit logs refreshed.';}catch(e){error.value=e instanceof Error?e.message:'Unable to load audit logs.';}finally{loading.value=false;}}async function inspect(r:Row){loading.value=true;try{detail.value=await get<Row>(`/api/v1/audit/${r.id}`);open.value=true;}catch(e){error.value=e instanceof Error?e.message:'Unable to load audit details.';}finally{loading.value=false;}}function clear(){search.value=moduleFilter.value=actionFilter.value=from.value=to.value='';}function exportCsv(){const values=[['Time','User','Module','Action','Description','IP Address'],...filtered.value.map(r=>[r.created_at,r.username,r.module,r.action,r.description,r.ip_address])],csv=values.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`audit_logs_${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);}
onMounted(()=>void load());
</script>
<template><div class="space-y-4 overflow-x-hidden pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Security and compliance" title="Audit Logs" description="Review user actions, system events, and operational history across NexusBox."><template #actions><NxButton variant="secondary" :disabled="loading" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton><NxButton :disabled="!filtered.length" @click="exportCsv">Export CSV</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><NxToolbar><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-[minmax(240px,2fr)_repeat(4,minmax(150px,1fr))_auto]"><label class="grid gap-1 text-xs font-semibold">Search<input v-model="search" placeholder="User, module, action, description, IP…" :class="inputClass"></label><label class="grid gap-1 text-xs font-semibold">Module<select v-model="moduleFilter" :class="inputClass"><option value="">All Modules</option><option v-for="m in modules" :key="m">{{m}}</option></select></label><label class="grid gap-1 text-xs font-semibold">Action<select v-model="actionFilter" :class="inputClass"><option value="">All Actions</option><option v-for="a in actions" :key="a">{{a}}</option></select></label><label class="grid gap-1 text-xs font-semibold">From<input v-model="from" type="date" :class="inputClass"></label><label class="grid gap-1 text-xs font-semibold">To<input v-model="to" type="date" :class="inputClass"></label><NxButton class="self-end" variant="secondary" @click="clear">Clear</NxButton></div></NxToolbar><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="c in [['Matching Logs',counts.total,'Current filter result'],['Today',counts.today,'Events today'],['Last 7 Days',counts.week,'Recent activity'],['Last 30 Days',counts.month,'Monthly activity']]" :key="String(c[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{c[0]}}</p><p class="mt-2 text-2xl font-bold">{{c[1]}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">{{c[2]}}</p></NxCard></section><NxTableShell min-width="1100px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Time</th><th class="px-4 py-3">Actor</th><th class="px-4 py-3">Module</th><th class="px-4 py-3">Action</th><th class="px-4 py-3">Description</th><th class="px-4 py-3">IP Address</th><th class="px-4 py-3 text-right">Details</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="7" class="p-12 text-center text-[var(--nx-text-muted)]">No audit records match the current filters.</td></tr><tr v-for="r in filtered" :key="r.id"><td class="whitespace-nowrap px-4 py-3">{{fmt(r.created_at)}}</td><td class="px-4 py-3"><b>{{r.username||'SYSTEM'}}</b><small v-if="r.actor_role" class="block text-[var(--nx-text-muted)]">{{r.actor_role}}</small></td><td class="px-4 py-3"><NxBadge tone="neutral">{{r.module||'—'}}</NxBadge></td><td class="px-4 py-3"><NxBadge :tone="tone(r.action)">{{r.action||'—'}}</NxBadge></td><td class="max-w-xl px-4 py-3">{{r.description||'—'}}</td><td class="px-4 py-3 font-mono">{{r.ip_address||'—'}}</td><td class="px-4 py-3 text-right"><NxButton variant="secondary" :disabled="loading" @click="inspect(r)">Inspect</NxButton></td></tr></tbody></NxTableShell><NxModal :open="open" title="Audit Event Details" :description="`${detail?.module||'System'} · ${detail?.action||'Event'} · ${fmt(detail?.created_at)}`" max-width="64rem" @close="open=false"><div class="grid gap-4 p-6 md:grid-cols-2"><div v-for="[k,v] in Object.entries(detail||{})" :key="k" class="min-w-0 rounded-md bg-[var(--nx-surface-muted)] p-3" :class="['metadata','old_values','new_values','context'].includes(k)?'md:col-span-2':''"><p class="text-xs font-bold uppercase text-[var(--nx-text-muted)]">{{k.replaceAll('_',' ')}}</p><pre v-if="typeof v==='object'" class="mt-2 overflow-auto whitespace-pre-wrap text-xs">{{JSON.stringify(v,null,2)}}</pre><p v-else class="mt-1 break-all text-sm">{{v??'—'}}</p></div></div><template #footer><NxButton variant="secondary" @click="open=false">Close</NxButton></template></NxModal></div></template>
<style scoped>:global([data-nx-next-root="audit"]){max-width:100%;overflow-x:hidden}</style>
